# A keyless rehearsal of the sovereign's opening paste for C2a-prime, run on steel by a session with no key.
# Derived from transcripts/PUSH-c2a-prime-opening.md on main: the clock check skipped, the minute check true,
# the wait capped at 24 tries, the grant, the fix and the push echoed; all in a scratch clone whose push URL
# is invalid. Never proposed; run by `git show FETCH_HEAD:transcripts/rehearsal/sitting-paste.sh | bash`.
set -u
C="$PWD/rehearsal-clone"
echo "== his checkout"; git -C ~/git/jack status -sb | head -3
git -C ~/git/jack rev-parse --verify -q refs/heads/opening-c2a-prime-3-push >/dev/null && echo "NOTE: a branch opening-c2a-prime-3-push exists in ~/git/jack"
[ -e ~/git/worktrees/jack/opening-c2a-prime-3-push ] && echo "NOTE: the path ~/git/worktrees/jack/opening-c2a-prime-3-push exists"
echo "== tools"; git --version; python3 --version; gh --version | head -1; echo "bash $BASH_VERSION"; "${GH_REAL:-gh}" auth status 2>&1 | grep -E 'Logged in|Token:'
echo "== clone"; git clone -q --reference ~/git/jack https://github.com/renavondata/jack "$C" && git -C "$C" remote set-url --push origin no-push-in-rehearsal && git -C "$C" log -1 --format='%h %s' origin/opening-c2a-prime-3
echo "== the paste, rehearsed (entries and the push echoed, the clock check skipped, the wait at most 12 minutes)"
cd "$C" && git switch main && [ "$("${GH_REAL:-gh}" api user --jq .login)" = gfrmin ] && echo "REHEARSAL: clock check skipped" && n=0 && until [ "$((n+=1))" -gt 24 ] || { [ "$(gh api 'repos/renavondata/jack/pulls?state=open&per_page=100' --jq 'map(select(.number!=125 and .number!=316 and .number!=562))|length')" = 0 ] && true; }; do echo "waiting: a proposal is open, or the minute is before 40"; sleep 30; done && [ "$n" -le 24 ] && git pull --ff-only && python3 -c 'import json; E=[json.loads(l) for l in open("log.jsonl")]; assert [e["seq"] for e in E if e["type"]=="push"][-1:] == [367] and sum(e["type"]=="push" for e in E) == 7 and not any(e["type"]=="decision" and e["body"].get("kind")=="promote" and e["body"].get("subject")=="C2a" for e in E)' && git fetch origin && git worktree add -b opening-c2a-prime-3-push "$C-wt" origin/opening-c2a-prime-3 && [ "$(git -C "$C-wt" rev-parse HEAD)" = ced344f9363ce9149e97044027107317b14a4c69 ] && python3 -c 'import runpy; runpy.run_path("tools/jack")["push_read_gate"]("opening-c2a-prime-3-push", "C2a-prime")' && echo "REHEARSAL: would enter decision grant" && echo "REHEARSAL: would enter decision fix" && git fetch origin && git -C "$C-wt" merge --no-ff --no-edit origin/main -m "merge: main into the opening branch of C2a-prime, after the grant and the fix" -m "Proposer: guy guy-master" && echo "REHEARSAL: would push: tools/jack push opening-c2a-prime-3-push --opens C2a-prime --review $C-wt/transcripts/REVIEW-C2a-prime-code.md" || echo "REHEARSAL STOPPED at the step above"
echo "== the scratch branch after the merge"; git -C "$C-wt" log -3 --format='%h %an | %(trailers:key=Proposer,valueonly,separator=%x20) | %s' 2>&1 | cut -c1-140
echo "== cleanup"; git -C "$C" worktree remove --force "$C-wt"; rm -rf "$C"; git -C ~/git/jack worktree remove --force ~/git/worktrees/jack/read-sitting-rehearsal-1 2>/dev/null && echo "removed the first attempt's worktree"; git -C ~/git/jack status -sb | head -1
